# Let's manually examine what happens in each case
pairs = [
    ('au', 'cu'),   # a->c
    ('gb', 'gd'),   # b->d
    ('zh', 'eaxde'), # z->eaxd, h->e (this looks complex)
    ('vg', 'vg'),   # no change
    ('fvbk', 'fvdk') # b->d, k->
]

for i, (inp, outp) in enumerate(pairs):
    print(f"Pair {i}: '{inp}' -> '{outp}'")
    if inp != outp:
        # Find differences
        min_len = min(len(inp), len(outp))
        diff_positions = []
        for j in range(min_len):
            if inp[j] != outp[j]:
                diff_positions.append((j, inp[j], outp[j]))

        # Check if we have length differences
        if len(inp) != len(outp):
            if len(inp) > len(outp):
                # Deletion
                print(f"  Length change: deleted at end")
            else:
                # Insertion
                print(f"  Length change: inserted at end")

        if diff_positions:
            for pos, old_char, new_char in diff_positions:
                print(f"  Position {pos}: '{old_char}' -> '{new_char}'")
        else:
            print("  No character differences found")
    print()

